/**
 * Deletes aged FB_Integration_Log__c rows on a nightly schedule.
 * Non-ERROR logs (including a blank Level__c) are removed after 30 days.
 * ERROR logs are kept until they are more than 180 days old.
 *
 * The purge runs in the schedulable transaction so one scheduled execution
 * finishes the delete. Sharing is ignored: this is system maintenance and
 * must see every log, not only rows shared with the scheduling user.
 */
public without sharing class LogPurgeJob implements Schedulable {

    private static final Integer STANDARD_RETENTION_DAYS = 30;
    private static final Integer ERROR_RETENTION_DAYS = 180;
    private static final String JOB_NAME = 'Log purge (nightly)';
    private static final String NIGHTLY_CRON = '0 0 2 * * ?';

    public LogPurgeJob() {
    }

    /**
     * Schedules a daily 02:00 run in the scheduling user's time zone.
     * @return CronTrigger Id from System.schedule
     */
    public static Id scheduleNightly() {
        return System.schedule(JOB_NAME, NIGHTLY_CRON, new LogPurgeJob());
    }

    public void execute(SchedulableContext context) {
        Datetime standardCutoff = Datetime.now().addDays(-STANDARD_RETENTION_DAYS);
        Datetime errorCutoff = Datetime.now().addDays(-ERROR_RETENTION_DAYS);

        // != does not match null in SOQL, so a blank Level__c is selected on
        // its own. Those rows use the 30-day retention, not the ERROR retention.
        // String comparison is case-insensitive, so 'error' and 'ERROR' match.
        List<FB_Integration_Log__c> expired = [
            SELECT Id
            FROM FB_Integration_Log__c
            WHERE (
                    CreatedDate < :standardCutoff
                    AND Level__c != 'ERROR'
                )
                OR (
                    CreatedDate < :standardCutoff
                    AND Level__c = null
                )
                OR (
                    CreatedDate < :errorCutoff
                    AND Level__c = 'ERROR'
                )
        ];

        if (expired.isEmpty()) {
            return;
        }

        delete expired;

        // Recycle-bin rows still count against data storage. Hard-delete is
        // best-effort: a missing permission must not roll back the purge.
        try {
            Database.emptyRecycleBin(expired);
        } catch (Exception ex) {
            // Soft delete already removed the rows from the active table.
        }
    }
}
