```apex
public with sharing class Opportunities extends fflib_SObjectDomain
{
    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String MSG_NEGATIVE_AMOUNT = 'Amount cannot be negative.';
    private static final String MSG_WON_AMOUNT_LOCKED = 'Amount cannot change on a won opportunity.';

    // fflib calls onValidate from after insert/update. addError in after context does not
    // reject individual rows for allOrNone=false, so the same hooks are run from before.
    private static Boolean validatedInBefore = false;
    private static Set<String> flaggedKeys = new Set<String>();

    public Opportunities(List<Opportunity> sObjectList)
    {
        super(sObjectList);
    }

    public override void onBeforeInsert()
    {
        validatedInBefore = true;
        onValidate();
    }

    public override void onBeforeUpdate(Map<Id, SObject> existingRecords)
    {
        validatedInBefore = true;
        onValidate(existingRecords);
    }

    public override void onValidate()
    {
        if (skipBecauseBeforePhaseAlreadyValidated())
        {
            return;
        }
        applyNegativeAmountRule();
    }

    public override void onValidate(Map<Id, SObject> existingRecords)
    {
        if (skipBecauseBeforePhaseAlreadyValidated())
        {
            return;
        }
        applyNegativeAmountRule();
        applyWonAmountLockedRule(existingRecords);
    }

    private Boolean skipBecauseBeforePhaseAlreadyValidated()
    {
        return Trigger.isExecuting && Trigger.isAfter && validatedInBefore;
    }

    private void applyNegativeAmountRule()
    {
        List<Opportunity> opps = (List<Opportunity>) Records;
        for (Integer i = 0; i < opps.size(); i++)
        {
            Opportunity opp = opps[i];
            if (opp.Amount != null && opp.Amount < 0)
            {
                addAmountError(opp, i, MSG_NEGATIVE_AMOUNT);
            }
        }
    }

    private void applyWonAmountLockedRule(Map<Id, SObject> existingRecords)
    {
        if (existingRecords == null)
        {
            return;
        }

        List<Opportunity> opps = (List<Opportunity>) Records;
        for (Integer i = 0; i < opps.size(); i++)
        {
            Opportunity opp = opps[i];
            Opportunity oldOpp = (Opportunity) existingRecords.get(opp.Id);
            // Old stage must already be Closed Won. Winning and changing Amount
            // in the same update is allowed.
            if (oldOpp != null
                && oldOpp.StageName == STAGE_CLOSED_WON
                && opp.Amount != oldOpp.Amount)
            {
                addAmountError(opp, i, MSG_WON_AMOUNT_LOCKED);
            }
        }
    }

    private void addAmountError(Opportunity opp, Integer index, String message)
    {
        Opportunity target = resolveTriggerRow(opp, index);
        String key = System.identityHashCode(target) + ':' + message;
        if (!flaggedKeys.add(key))
        {
            return;
        }

        // Records the message in fflib_SObjectDomain.Errors for unit tests.
        error(message, opp, Opportunity.Amount);

        if (Trigger.isExecuting)
        {
            target.Amount.addError(message);
        }
    }

    private Opportunity resolveTriggerRow(Opportunity opp, Integer index)
    {
        if (!Trigger.isExecuting)
        {
            return opp;
        }
        if (opp.Id != null && Trigger.newMap != null && Trigger.newMap.containsKey(opp.Id))
        {
            return (Opportunity) Trigger.newMap.get(opp.Id);
        }
        if (Trigger.new != null && index < Trigger.new.size())
        {
            Opportunity row = (Opportunity) Trigger.new[index];
            if (row === opp || opp.Id == null || row.Id == opp.Id)
            {
                return row;
            }
        }
        return opp;
    }

    public class Constructor implements fflib_SObjectDomain.IConstructable
    {
        public fflib_SObjectDomain construct(List<SObject> sObjectList)
        {
            return new Opportunities(sObjectList);
        }
    }
}
