/**
 * Records a gift that has already been received as a Closed Won NPSP donation.
 * Household contact roles and the single paid payment are written explicitly so the
 * result does not depend on org naming or soft-credit settings. Opportunity naming
 * automation is suspended for the transaction so the required name is not overwritten.
 */
public with sharing class GiftService {

    private static final String STAGE_CLOSED_WON = 'Closed Won';
    private static final String ROLE_DONOR = 'Donor';
    private static final String ROLE_HOUSEHOLD_MEMBER = 'Household Member';

    /**
     * Records a Closed Won donation of {@code amount} from the contact, closed on
     * {@code giftDate}, and returns the Opportunity Id.
     *
     * @throws IllegalArgumentException if the contact does not exist, the contact has
     *         no household account, {@code amount} is null, zero, or negative, or
     *         {@code giftDate} is null.
     */
    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {
        validateInputs(contactId, amount, giftDate);

        Contact donor = queryDonor(contactId);
        HouseholdCrediting crediting = new HouseholdCrediting();
        Set<Id> householdContactIds = crediting.householdContactIds(donor.AccountId);
        householdContactIds.add(donor.Id);

        String desiredName = buildOpportunityName(donor, giftDate);
        Opportunity gift = new Opportunity(
            Name = desiredName,
            AccountId = donor.AccountId,
            Amount = amount,
            CloseDate = giftDate,
            StageName = STAGE_CLOSED_WON,
            npsp__Primary_Contact__c = donor.Id,
            npe01__Do_Not_Automatically_Create_Payment__c = true,
            npsp__DisableContactRoleAutomation__c = true
        );

        NamingGuard naming = new NamingGuard();
        naming.suspend();
        try {
            insert gift;
            crediting.synchronize(gift.Id, donor.Id, householdContactIds, amount, giftDate);
            // A payment write can update the opportunity. Put the header back, then
            // synchronize once more so that update cannot leave a duplicate child.
            if (enforceHeader(gift.Id, donor, amount, giftDate)) {
                crediting.synchronize(gift.Id, donor.Id, householdContactIds, amount, giftDate);
            }
            crediting.enforceName(gift.Id, desiredName);
            return gift.Id;
        } finally {
            naming.restore();
        }
    }

    private static void validateInputs(Id contactId, Decimal amount, Date giftDate) {
        if (contactId == null || contactId.getSObjectType() != Contact.SObjectType) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException('Amount must be greater than zero.');
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }
    }

    private static Contact queryDonor(Id contactId) {
        List<Contact> donors = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (donors.isEmpty()) {
            throw new IllegalArgumentException('Contact does not exist.');
        }
        if (donors[0].AccountId == null) {
            throw new IllegalArgumentException('Contact does not belong to a household account.');
        }
        return donors[0];
    }

    private static String buildOpportunityName(Contact donor, Date giftDate) {
        String who = String.isBlank(donor.FirstName)
            ? donor.LastName
            : donor.FirstName + ' ' + donor.LastName;
        return who + ' Donation ' + String.valueOf(giftDate);
    }

    /**
     * @return true when the header had to be rewritten. Callers then resynchronize
     *         children, because an amount or stage change can make NPSP add a payment.
     */
    private static Boolean enforceHeader(Id opportunityId, Contact donor, Decimal amount, Date giftDate) {
        Opportunity current = [
            SELECT Amount, CloseDate, StageName, AccountId, npsp__Primary_Contact__c,
                   npe01__Do_Not_Automatically_Create_Payment__c,
                   npsp__DisableContactRoleAutomation__c
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        Opportunity patch = new Opportunity(Id = opportunityId);
        Boolean changed = false;
        if (current.Amount != amount) {
            patch.Amount = amount;
            changed = true;
        }
        if (current.CloseDate != giftDate) {
            patch.CloseDate = giftDate;
            changed = true;
        }
        if (current.StageName != STAGE_CLOSED_WON) {
            patch.StageName = STAGE_CLOSED_WON;
            changed = true;
        }
        if (current.AccountId != donor.AccountId) {
            patch.AccountId = donor.AccountId;
            changed = true;
        }
        if (current.npsp__Primary_Contact__c != donor.Id) {
            patch.npsp__Primary_Contact__c = donor.Id;
            changed = true;
        }
        if (current.npe01__Do_Not_Automatically_Create_Payment__c != true) {
            patch.npe01__Do_Not_Automatically_Create_Payment__c = true;
            changed = true;
        }
        if (current.npsp__DisableContactRoleAutomation__c != true) {
            patch.npsp__DisableContactRoleAutomation__c = true;
            changed = true;
        }
        if (changed) {
            update patch;
        }
        return changed;
    }

    /**
     * Deactivates NPSP opportunity-naming handlers in the transaction cache only.
     * TDTM_TriggerHandler is not global, so unmanaged code cannot set its bypass flag.
     */
    private class NamingGuard {
        private List<npsp__Trigger_Handler__c> handlers;
        private List<Boolean> priorActive;
        private Boolean suspended = false;

        public void suspend() {
            handlers = npsp.TDTM_Config_API.getCachedRecords();
            priorActive = new List<Boolean>();
            if (handlers != null) {
                for (npsp__Trigger_Handler__c handler : handlers) {
                    priorActive.add(handler.npsp__Active__c);
                    if (isNamingHandler(handler)) {
                        handler.npsp__Active__c = false;
                    }
                }
                npsp.TDTM_Config_API.setCachedRecords(handlers);
            }
            suspended = true;
        }

        public void restore() {
            if (!suspended || handlers == null) {
                suspended = false;
                return;
            }
            Integer limitSize = Math.min(handlers.size(), priorActive.size());
            for (Integer i = 0; i < limitSize; i++) {
                handlers[i].npsp__Active__c = priorActive[i];
            }
            npsp.TDTM_Config_API.setCachedRecords(handlers);
            suspended = false;
        }

        private Boolean isNamingHandler(npsp__Trigger_Handler__c handler) {
            String className = handler.npsp__Class__c == null
                ? ''
                : handler.npsp__Class__c.toLowerCase();
            return className.contains('opportunitynaming');
        }
    }

    /**
     * Credits every household member, including members the running user cannot see.
     * The donor lookup stays in the outer class, so an invisible contact is rejected.
     */
    private without sharing class HouseholdCrediting {

        public Set<Id> householdContactIds(Id accountId) {
            Set<Id> contactIds = new Set<Id>();
            for (Contact member : [
                SELECT Id
                FROM Contact
                WHERE AccountId = :accountId
            ]) {
                contactIds.add(member.Id);
            }
            return contactIds;
        }

        public void synchronize(
            Id opportunityId,
            Id donorId,
            Set<Id> householdContactIds,
            Decimal amount,
            Date giftDate
        ) {
            synchronizeRoles(opportunityId, donorId, householdContactIds);
            synchronizePayment(opportunityId, amount, giftDate);
        }

        public void enforceName(Id opportunityId, String desiredName) {
            Opportunity current = [
                SELECT Name
                FROM Opportunity
                WHERE Id = :opportunityId
                LIMIT 1
            ];
            if (current.Name != desiredName) {
                update new Opportunity(Id = opportunityId, Name = desiredName);
            }
        }

        private void synchronizeRoles(Id opportunityId, Id donorId, Set<Id> householdContactIds) {
            List<OpportunityContactRole> existing = [
                SELECT Id, ContactId, Role, IsPrimary
                FROM OpportunityContactRole
                WHERE OpportunityId = :opportunityId
                ORDER BY CreatedDate ASC, Id ASC
            ];

            Map<Id, OpportunityContactRole> keeperByContact = new Map<Id, OpportunityContactRole>();
            List<OpportunityContactRole> toDelete = new List<OpportunityContactRole>();
            for (OpportunityContactRole role : existing) {
                if (role.ContactId == null
                    || !householdContactIds.contains(role.ContactId)
                    || keeperByContact.containsKey(role.ContactId)) {
                    toDelete.add(role);
                } else {
                    keeperByContact.put(role.ContactId, role);
                }
            }
            if (!toDelete.isEmpty()) {
                delete toDelete;
            }

            List<OpportunityContactRole> roleUpdates = new List<OpportunityContactRole>();
            List<OpportunityContactRole> toInsert = new List<OpportunityContactRole>();
            for (Id memberId : householdContactIds) {
                Boolean isDonor = memberId == donorId;
                String desiredRole = isDonor ? ROLE_DONOR : ROLE_HOUSEHOLD_MEMBER;
                OpportunityContactRole keeper = keeperByContact.get(memberId);
                if (keeper == null) {
                    toInsert.add(new OpportunityContactRole(
                        OpportunityId = opportunityId,
                        ContactId = memberId,
                        Role = desiredRole,
                        IsPrimary = false
                    ));
                    continue;
                }
                if (keeper.Role != desiredRole || (keeper.IsPrimary && !isDonor)) {
                    keeper.Role = desiredRole;
                    if (!isDonor) {
                        keeper.IsPrimary = false;
                    }
                    roleUpdates.add(keeper);
                }
            }
            if (!roleUpdates.isEmpty()) {
                update roleUpdates;
            }
            if (!toInsert.isEmpty()) {
                insert toInsert;
            }
            enforceSinglePrimary(opportunityId, donorId);
        }

        /**
         * Clears every other primary before marking the donor, so two contact roles
         * are never primary in the same DML statement.
         */
        private void enforceSinglePrimary(Id opportunityId, Id donorId) {
            List<OpportunityContactRole> roles = [
                SELECT Id, ContactId, Role, IsPrimary
                FROM OpportunityContactRole
                WHERE OpportunityId = :opportunityId
                ORDER BY CreatedDate ASC, Id ASC
            ];

            List<OpportunityContactRole> duplicates = new List<OpportunityContactRole>();
            Set<Id> seen = new Set<Id>();
            List<OpportunityContactRole> clearPrimary = new List<OpportunityContactRole>();
            OpportunityContactRole donorRole;
            for (OpportunityContactRole role : roles) {
                if (!seen.add(role.ContactId)) {
                    duplicates.add(role);
                    continue;
                }
                if (role.ContactId == donorId) {
                    donorRole = role;
                } else if (role.IsPrimary) {
                    role.IsPrimary = false;
                    clearPrimary.add(role);
                }
            }
            if (!duplicates.isEmpty()) {
                delete duplicates;
            }
            if (!clearPrimary.isEmpty()) {
                update clearPrimary;
            }
            if (donorRole != null && (donorRole.IsPrimary != true || donorRole.Role != ROLE_DONOR)) {
                update new OpportunityContactRole(
                    Id = donorRole.Id,
                    Role = ROLE_DONOR,
                    IsPrimary = true
                );
            }
        }

        private void synchronizePayment(Id opportunityId, Decimal amount, Date giftDate) {
            List<npe01__OppPayment__c> payments = [
                SELECT Id,
                       npe01__Payment_Amount__c,
                       npe01__Payment_Date__c,
                       npe01__Scheduled_Date__c,
                       npe01__Paid__c
                FROM npe01__OppPayment__c
                WHERE npe01__Opportunity__c = :opportunityId
                ORDER BY CreatedDate ASC, Id ASC
            ];

            if (payments.isEmpty()) {
                insert newPayment(opportunityId, null, amount, giftDate);
            } else {
                List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();
                for (Integer i = 1; i < payments.size(); i++) {
                    extras.add(new npe01__OppPayment__c(Id = payments[i].Id));
                }
                if (!extras.isEmpty()) {
                    delete extras;
                }

                npe01__OppPayment__c keeper = payments[0];
                Boolean keeperCorrect = keeper.npe01__Paid__c == true
                    && keeper.npe01__Payment_Amount__c == amount
                    && keeper.npe01__Payment_Date__c == giftDate
                    && keeper.npe01__Scheduled_Date__c == giftDate;
                if (!keeperCorrect) {
                    update newPayment(opportunityId, keeper.Id, amount, giftDate);
                }
            }

            // Rewriting the keeper can cause NPSP to insert the outstanding balance
            // as another payment. Remove that extra without touching the keeper again.
            List<npe01__OppPayment__c> afterWrite = [
                SELECT Id
                FROM npe01__OppPayment__c
                WHERE npe01__Opportunity__c = :opportunityId
                ORDER BY CreatedDate ASC, Id ASC
            ];
            if (afterWrite.size() > 1) {
                List<npe01__OppPayment__c> extras = new List<npe01__OppPayment__c>();
                for (Integer i = 1; i < afterWrite.size(); i++) {
                    extras.add(afterWrite[i]);
                }
                delete extras;
            }
        }

        private npe01__OppPayment__c newPayment(
            Id opportunityId,
            Id paymentId,
            Decimal amount,
            Date giftDate
        ) {
            npe01__OppPayment__c payment = new npe01__OppPayment__c(
                npe01__Payment_Amount__c = amount,
                npe01__Payment_Date__c = giftDate,
                npe01__Scheduled_Date__c = giftDate,
                npe01__Paid__c = true
            );
            if (paymentId == null) {
                payment.npe01__Opportunity__c = opportunityId;
            } else {
                payment.Id = paymentId;
            }
            return payment;
        }
    }
}
