/**
 * Formula context for Account entry criteria.
 * record / recordPrior expose the new and prior Account.
 * rating / ratingPrior expose Rating as text so formulas can compare it
 * without picklist functions (FormulaEval does not support ISPICKVAL).
 */
public with sharing class AccountTriggerRecord extends TriggerRecord {
    public Account record {
        get {
            return (Account) this.newSobject;
        }
        set {
            this.newSobject = value;
        }
    }

    public Account recordPrior {
        get {
            return (Account) this.oldSobject;
        }
        set {
            this.oldSobject = value;
        }
    }

    public String rating {
        get {
            return textValue(this.newSobject, 'Rating');
        }
        set {
            putValue(this.newSobject, 'Rating', value);
        }
    }

    public String ratingPrior {
        get {
            return textValue(this.oldSobject, 'Rating');
        }
        set {
            putValue(this.oldSobject, 'Rating', value);
        }
    }

    private static String textValue(SObject source, String fieldName) {
        if (source == null || source.get(fieldName) == null) {
            return '';
        }
        return String.valueOf(source.get(fieldName));
    }

    private static void putValue(SObject source, String fieldName, String value) {
        if (source != null) {
            source.put(fieldName, value);
        }
    }
}
