/**
 * Maintains Account.FB_Open_Case_Count__c as the number of related Cases
 * with IsClosed = false.
 *
 * Runs without sharing so the recount sees every Case and still updates
 * Account when the running user cannot see every Case. Cases with no
 * Account are ignored. An Account that loses its last open Case is set
 * to 0, not null.
 *
 * Parents are locked before the aggregate so concurrent Case changes cannot
 * overwrite each other's recount. FOR UPDATE locks rows in Id order; an
 * explicit ORDER BY is not allowed. One locking query, one aggregate query
 * and one Account update per execution.
 */
public without sharing class TA_Case_RollupOpenCount implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate, TriggerAction.AfterDelete, TriggerAction.AfterUndelete {
    public void afterInsert(List<SObject> triggerNew) {
        rollup(openAccountIds(triggerNew));
    }

    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> accountIds = new Set<Id>();
        for (Integer i = 0; i < triggerNew.size(); i++) {
            Case newCase = (Case) triggerNew[i];
            Case oldCase = (Case) triggerOld[i];
            if (newCase.AccountId == oldCase.AccountId && newCase.IsClosed == oldCase.IsClosed) {
                continue;
            }
            addIfOpen(accountIds, oldCase);
            addIfOpen(accountIds, newCase);
        }
        rollup(accountIds);
    }

    public void afterDelete(List<SObject> triggerOld) {
        rollup(openAccountIds(triggerOld));
    }

    public void afterUndelete(List<SObject> triggerNew) {
        rollup(openAccountIds(triggerNew));
    }

    private static Set<Id> openAccountIds(List<SObject> caseRecords) {
        Set<Id> accountIds = new Set<Id>();
        for (SObject caseRecord : caseRecords) {
            addIfOpen(accountIds, (Case) caseRecord);
        }
        return accountIds;
    }

    private static void addIfOpen(Set<Id> accountIds, Case caseRecord) {
        if (caseRecord.AccountId != null && caseRecord.IsClosed == false) {
            accountIds.add(caseRecord.AccountId);
        }
    }

    private static void rollup(Set<Id> accountIds) {
        if (accountIds.isEmpty()) {
            return;
        }

        List<Account> lockedAccounts = [
            SELECT Id
            FROM Account
            WHERE Id IN :accountIds
            FOR UPDATE
        ];
        if (lockedAccounts.isEmpty()) {
            return;
        }

        Map<Id, Integer> openCountByAccountId = new Map<Id, Integer>();
        for (Account lockedAccount : lockedAccounts) {
            openCountByAccountId.put(lockedAccount.Id, 0);
        }
        for (AggregateResult aggregated : [
            SELECT AccountId, COUNT(Id) openCount
            FROM Case
            WHERE AccountId IN :openCountByAccountId.keySet() AND IsClosed = FALSE
            GROUP BY AccountId
        ]) {
            openCountByAccountId.put((Id) aggregated.get('AccountId'), (Integer) aggregated.get('openCount'));
        }

        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : openCountByAccountId.keySet()) {
            Account accountToUpdate = new Account(Id = accountId);
            accountToUpdate.FB_Open_Case_Count__c = openCountByAccountId.get(accountId);
            accountsToUpdate.add(accountToUpdate);
        }
        update accountsToUpdate;
    }
}
